I will read the active sheet’s inventory layers (beginning inventory plus PO-1 through PO-4) and current inventory from the cached values. For each row, I will allocate the current inventory from the newest layer backward under FIFO and divide the accumulated cost by current inventory. The script writes the resulting per-unit costs as plain numbers into M2:M5.

```python
import shutil
import openpyxl

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

ws = wb.active
vws = vals.active

def to_float(value):
    if value is None:
        return 0.0
    if isinstance(value, bool):
        return float(value)
    if isinstance(value, (int, float)):
        return float(value)
    s = str(value).strip().replace(",", "")
    if not s:
        return 0.0
    try:
        return float(s)
    except ValueError:
        return 0.0

# Layers in chronological order:
# Beginning inventory, PO-1, PO-2, PO-3, PO-4
layer_cols = [
    (2, 3),   # B, C
    (4, 5),   # D, E
    (6, 7),   # F, G
    (8, 9),   # H, I
    (10, 11)  # J, K
]

for r in range(2, 6):
    current_raw = vws.cell(row=r, column=12).value  # Column L
    if current_raw is None:
        ws.cell(row=r, column=13).value = None
        print(f"row {r}: no current inventory")
        continue

    current = to_float(current_raw)
    layers = []

    for units_col, cost_col in layer_cols:
        units = to_float(vws.cell(row=r, column=units_col).value)
        cost = to_float(vws.cell(row=r, column=cost_col).value)
        if units > 0:
            layers.append((units, cost))

    remaining = current
    total_cost = 0.0

    # FIFO ending inventory: take from the most recent layers backward.
    for units, cost in reversed(layers):
        if remaining <= 0:
            break
        take = min(remaining, units)
        total_cost += take * cost
        remaining -= take

    if current > 0:
        per_unit_cost = total_cost / current
        if abs(per_unit_cost) < 1e-12:
            per_unit_cost = 0.0
        ws.cell(row=r, column=13).value = per_unit_cost
        print(f"row {r}: current={current}, per_unit_cost={per_unit_cost}")
    else:
        ws.cell(row=r, column=13).value = 0.0
        print(f"row {r}: current=0, per_unit_cost=0")

wb.save(OUT)
```

